// Mirrors app/lib/services/whisper.dart (Whisper.encode) and ble_link.dart (BleCodec.pack).
const b = $input.first().json.body || $input.first().json;
const kinds = ['blocking','lights_on','towing','window_open','accident','other'];
const langs = ['en','hi','kn','ta'];
const plate = String(b.plate || 'KA01AB1234').toUpperCase().replace(/[^A-Z0-9]/g,'');
const kind = kinds.includes(b.kind) ? b.kind : 'other';
const lang = langs.includes(b.lang) ? b.lang : 'en';
const nonce = Number.isInteger(b.nonce) ? b.nonce & 0xFFFF : Math.floor(Math.random()*65536);
const bits = [];
let acc = 0, nb = 0;
for (const ch of plate) {
  const c = ch.charCodeAt(0);
  acc = (acc << 6) | (c <= 0x39 ? c - 0x30 + 1 : c - 0x41 + 11);
  nb += 6;
  while (nb >= 8) { nb -= 8; bits.push((acc >> nb) & 0xFF); }
  acc &= (1 << nb) - 1;
}
if (nb > 0) bits.push((acc << (8 - nb)) & 0xFF);
const whisper = [0x11, (langs.indexOf(lang) << 4) | kinds.indexOf(kind), (nonce >> 8) & 0xFF, nonce & 0xFF, ...bits];
const advert = [0xC7, whisper.length, ...whisper];
const hex = a => a.map(x => x.toString(16).padStart(2,'0')).join(' ');
const couriers = Array.isArray(b.couriers) && b.couriers.length ? b.couriers : [{name:'Phone A (cab)', signal:false},{name:'Phone B (bike)', signal:false},{name:'Phone C (bus)', signal:true}];
return [{ json: { plate, kind, lang, nonce, couriers, whisperBytes: whisper.length, advertHex: hex(advert), advertBytes: advert.length, fitsLegacyAdvert: advert.length <= 27, text: 'Car ' + plate + ': ' + kind.replace('_',' ') } }];

// Store-carry-forward, as WhisperStore does: every phone that hears the advert keeps it
// and repeats it until some phone has a signal and delivers it; delivery stops the gossip.
const w = $('Encode the Bluetooth advert').first().json;
let pU = null; try { pU = $input.first().json.answers.q.noul; } catch (e) {}
const urgent = pU !== null && pU >= 0.5;
const trace = [{ step: 0, who: 'Sender', action: 'broadcasts advert ' + w.advertHex + ' (' + w.advertBytes + ' bytes), no signal' }];
let delivered = false, hops = 0, by = null;
for (const c of w.couriers) {
  hops++;
  if (c.signal) { trace.push({ step: hops, who: c.name, action: 'heard it over Bluetooth, HAS SIGNAL: delivers to server' }); delivered = true; by = c.name; break; }
  trace.push({ step: hops, who: c.name, action: 'heard it over Bluetooth, no signal: keeps it (carrying) and repeats it' });
}
if (delivered) trace.push({ step: hops + 1, who: 'Server', action: 'accepts once per nonce ' + w.nonce + '; owner notified; phones stop repeating' });
else trace.push({ step: hops + 1, who: 'Everyone', action: 'still carrying. Nobody had signal yet; the message waits' });
return [{ json: { ...w, pUrgent: pU, priority: urgent ? 'carry first' : 'normal', delivered, hops, deliveredBy: by, trace } }];

const r = $('Relay: store, carry, forward').first().json;
let msg = ''; try { msg = $input.first().json.choices[0].message.content.trim(); } catch (e) {}
return [{ json: { delivered: r.delivered, hops: r.hops, deliveredBy: r.deliveredBy, priority: r.priority,
  ownerNotification: r.delivered ? { car: r.plate, kind: r.kind, text: msg, via: 'Carried here by Bluetooth' } : null,
  advert: { hex: r.advertHex, bytes: r.advertBytes, fitsLegacyAdvert: r.fitsLegacyAdvert }, trace: r.trace } }];
